'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { ShieldCheck, User } from 'lucide-react';

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState<'admin' | 'officer'>('admin');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // TODO: Integrate Supabase Auth here
    // For Phase 1 Demo: Mock redirect based on selected role
    
    setTimeout(() => {
      if (role === 'admin') {
        router.push('/');
      } else {
        // Officer would go to a different view or mobile app
        // For now, redirect to dashboard with restricted view params
        router.push('/?view=officer'); 
      }
    }, 1000);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <div className="w-full max-w-md bg-surface border border-white/10 rounded-lg p-8 shadow-2xl">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-white tracking-tight mb-2">PAYPARQ.AI</h1>
          <p className="text-white/50">Tactical Parking Intelligence</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-semibold text-white/70 uppercase">Role Selection</label>
            <div className="grid grid-cols-2 gap-4">
              <button
                type="button"
                onClick={() => setRole('admin')}
                className={`flex items-center justify-center gap-2 p-3 rounded border transition-all ${
                  role === 'admin' 
                    ? 'bg-primary border-primary text-white' 
                    : 'bg-white/5 border-white/10 text-white/50 hover:bg-white/10'
                }`}
              >
                <ShieldCheck size={18} />
                Admin
              </button>
              <button
                type="button"
                onClick={() => setRole('officer')}
                className={`flex items-center justify-center gap-2 p-3 rounded border transition-all ${
                  role === 'officer' 
                    ? 'bg-primary border-primary text-white' 
                    : 'bg-white/5 border-white/10 text-white/50 hover:bg-white/10'
                }`}
              >
                <User size={18} />
                Officer
              </button>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-semibold text-white/70 uppercase">Email Access</label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-black/20 border border-white/10 rounded p-3 text-white focus:border-primary focus:outline-none transition-colors"
              placeholder="operator@payparq.ai"
            />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-semibold text-white/70 uppercase">Secure Token</label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-black/20 border border-white/10 rounded p-3 text-white focus:border-primary focus:outline-none transition-colors"
              placeholder="••••••••"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-primary hover:bg-primary-hover text-white font-bold py-3 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? 'AUTHENTICATING...' : 'ACCESS SYSTEM'}
          </button>
        </form>
      </div>
    </div>
  );
}
